class MinStack {
    Stack<Integer>stack;
    Stack<Integer>minStack;

    public MinStack() {
        stack = new Stack<>();
         minStack = new Stack<>();
    }
    
    public void push(int val) {
        stack.push(val);
        if(minStack.empty() || val<= minStack.peek()){
            minStack.push(val);
        }
    }
    
    public void pop() {
         int any=stack.peek();
         stack.pop();
         if(any==minStack.peek()){
            minStack.pop();
         }
    }
    
    public int top() {
        return stack.peek();
    }
    
    public int getMin() {
        return minStack.peek();
    }
}

